    complete = [("p1", "sA1", "sB1"), ("p2", "sA2", "sB2")]
    complete = [p for p in complete if p[1] in cells_of and p[2] in cells_of]
    n = len(complete)
    for g in kept_genes:
        d = [vals[g][a] - vals[g][b] for _, a, b in complete]
        md = sum(d)/n
        var = sum((x-md)**2 for x in d)/(n-1)
