    for row in csv.DictReader(h, delimiter="\t"):
        if row["retained"] == "true":
            kept_cells.add(row["cell_id"])
with open(f"{ROOT}/out/genes.tsv") as h:
    for row in csv.DictReader(h, delimiter="\t"):
        if row["retained"] == "true":
            kept_genes.append(row["gene_id"])

expected = {}
for cl in sorted(set(clusters.values())):
    cells_of = {}
    for cid in cell_ids:
        if cid in kept_cells and clusters[cid] == cl:
            cells_of.setdefault(cell_sample[cid], []).append(cid)
    totals = {s: sum(M[g][idx[c]] for g in kept_genes for c in cs)
              for s, cs in cells_of.items()}
    complete = [(a, b) for a, b in (("sA1", "sB1"), ("sA2", "sB2"))
                if a in cells_of and b in cells_of]
    n = len(complete)
    for g in kept_genes:
        v = {}
        for s, cs in cells_of.items():
            c = sum(M[g][idx[x]] for x in cs)
            v[s] = math.log1p(c / totals[s] * 10000) if totals[s] > 0 else 0.0
        d = [v[a] - v[b] for a, b in complete]
        md = sum(d) / n
        var = sum((x - md) ** 2 for x in d) / (n - 1)
        if var <= 0:
            t, p = (0.0, 1.0) if md == 0 else (math.inf if md > 0 else -math.inf, 0.0)
