    for row in csv.DictReader(h, delimiter="\t"):
        key = (int(row["cluster"]), row["gene_id"])
        md, t, p = expected[key]
        got = (float(row["mean_difference"]), float(row["t_stat"]),
               float(row["p_value"]))
        # BH adjusted p sanity
        for name, e, o in (("mean", md, got[0]), ("t", t, got[1]),
