        if not (0.0 <= adj <= 1.0) or adj < got[2] - 1e-15:
            print("BAD ADJ", key, got[2], adj)
            fails += 1
print("FAILS" if fails else "ALL MATCH", fails)
sys.exit(1 if fails else 0)

